def send_bot_dm(text: str) -> None:
    token, users = _load_bot_dm_config()
    url = f"https://api.telegram.org/bot{token}/sendMessage"
    for uid in users:
        body = json.dumps(
            {"chat_id": uid, "text": text, "disable_web_page_preview": True},
            ensure_ascii=False,
        ).encode("utf-8")
        req = urllib.request.Request(
            url,
            data=body,
            method="POST",
            headers={"Content-Type": "application/json; charset=utf-8"},
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                payload = json.loads(resp.read().decode("utf-8"))
            if not payload.get("ok"):
                print(f"! DM to {uid} not ok: {payload}", file=sys.stderr)
            else:
                print(f"DM ok → {uid}", flush=True)
        except urllib.error.HTTPError as e:
            err = e.read().decode("utf-8", errors="replace")
            print(f"! DM HTTP {e.code} to {uid}: {err}", file=sys.stderr)
        except Exception as e:  # noqa: BLE001
            print(f"! DM failed to {uid}: {e}", file=sys.stderr)


def _load_seen() -> set[str]:
    if not SEEN_PATH.exists():
        return set()
    try:
        data = json.loads(SEEN_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return set()
    keys = data.get("keys") or data.get("links") or []
    return {str(x) for x in keys if x}


def _save_seen(keys: set[str]) -> None:
    ordered = sorted(keys)
    if len(ordered) > SEEN_MAX:
        ordered = ordered[-SEEN_MAX:]
    SEEN_PATH.parent.mkdir(parents=True, exist_ok=True)
    SEEN_PATH.write_text(
        json.dumps(
            {
                "updated_at": datetime.now().isoformat(timespec="seconds"),
                "count": len(ordered),
                "keys": ordered,
            },
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )


def seed_seen_from_latest_scan(seen: set[str]) -> int:
    """把最近一次 scan 结果标成已见，避免 watch 启动后把旧岗再推一遍。"""
    files = sorted(OUT.glob("ethan_bigdata_jobs_*.json"))
    if not files:
        return 0
    try:
        payload = json.loads(files[-1].read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return 0
    before = len(seen)
    for j in payload.get("jobs") or []:
        link = j.get("link")
        if link:
            seen.add(link)
        cid, mid = j.get("chat_id"), j.get("message_id")
        if cid is not None and mid is not None:
            seen.add(f"{cid}:{mid}")
        text = (j.get("text") or "")[:120]
        if text:
            seen.add(f"t:{text}")
    return len(seen) - before


