    if isinstance(entity, Chat):
        return True
    return False


async def cmd_watch(*, remote_only: bool, min_len: int, announce: bool, dry_run: bool) -> None:
    """实时监听 Ethan 会话里的群/频道新消息，命中则 bot 私聊主人。"""
    seen = _load_seen()
    seeded = seed_seen_from_latest_scan(seen)
    if seeded:
        _save_seen(seen)
        print(f"已从最近 scan 种子已见键 +{seeded}（合计 {len(seen)}）", flush=True)

    client = _client()
    await client.connect()
    if not await client.is_user_authorized():
        raise SystemExit("未登录。请先: python3 scripts/ethan_channel_bigdata_jobs.py login")
    await ensure_ethan(client)

    if announce and not dry_run:
        send_bot_dm(
            "【岗位监控已开启】\n"
            "又初用 Ethan 账号实时盯未归档频道/群里的远程大数据相关招聘；"
            "有新命中会私聊你（同文去重）。\n"
            "停：launchctl unload ~/Library/LaunchAgents/com.youchu.ethan-jobs-watch.plist"
        )

    @client.on(events.NewMessage(incoming=True))
    async def _on_new(event: events.NewMessage.Event) -> None:  # noqa: ANN202
        try:
            chat = await event.get_chat()
            if not _is_group_or_channel(chat):
                return
            text = (event.message.message or "").strip()
            if len(text) < min_len:
                return
            ok, _job_hits, role_hits = is_job_like(text)
            if not ok:
                return
            title = getattr(chat, "title", None) or getattr(chat, "username", None) or str(event.chat_id)
            remote_ok, remote_hits = is_remote_job(text, str(title))
            if remote_only and not remote_ok:
                return

            username = getattr(chat, "username", None)
            chat_id = event.chat_id
            msg_id = event.message.id
            link = message_link(username, chat_id, msg_id)
            keys = {link, f"{chat_id}:{msg_id}", f"t:{text[:120]}"}
            if keys & seen:
                return
            seen.update(keys)
            _save_seen(seen)

            when = datetime.now().astimezone().strftime("%Y-%m-%d %H:%M")
            if event.message.date:
                md = event.message.date
                if md.tzinfo is None:
                    md = md.replace(tzinfo=timezone.utc)
                when = md.astimezone().strftime("%Y-%m-%d %H:%M")

            body = format_job_dm(
                title=str(title),
                roles=role_hits,
                remotes=remote_hits,
                link=link,
                text=text,
                when=when,
            )
            print(f"HIT {when} | {'、'.join(role_hits[:5])} | {link}", flush=True)
            if dry_run:
                print("--- dry-run DM ---\n" + body, flush=True)
                return
            send_bot_dm(body)
        except Exception as e:  # noqa: BLE001
            print(f"! watch handler error: {e}", file=sys.stderr)

    loc = "仅远程" if remote_only else "含到岗"
    print(f"watch 已启动（{loc} · min_len={min_len} · dry_run={dry_run}），监听群/频道新消息…", flush=True)
    await client.run_until_disconnected()


